namespace Orchestration.API.Tests.Engineering.Intelligence;
public sealed class ArchitectureOwnershipTests{[Fact]public void Frontend_routes_are_thin_proxies(){var root=FindRoot();foreach(var n in new[]{"sap","windchill","assemble"}){var t=File.ReadAllText(Path.Combine(root,"OrchestrationPlatform","frontend","app","api","engineering","intelligence",n,"route.ts"));Assert.DoesNotContain("IntelligenceEntity",t);Assert.DoesNotContain("legacyHandoffToIntelligence",t);Assert.Contains("/api/engineering/intelligence/handoff",t);}}[Fact]public void Runtime_has_no_silent_fallback(){var t=File.ReadAllText(Path.Combine(FindRoot(),"OrchestrationPlatform","frontend","features","lattice-next","infrastructure","intelligence-runtime.ts"));Assert.DoesNotContain("legacyHandoffToIntelligence",t);Assert.DoesNotContain("legacy-compatibility",t);}static string FindRoot(){var d=new DirectoryInfo(AppContext.BaseDirectory);while(d is not null&&!Directory.Exists(Path.Combine(d.FullName,"OrchestrationPlatform")))d=d.Parent;return d?.FullName??throw new DirectoryNotFoundException();}}
